using RealmForge.Domain.Entities;
using RealmForge.Shared.Enums;

namespace RealmForge.Infrastructure.Persistence.Seeding.ClassesData;

///	<summary>
///	Wild Magic (sorcerer, 2014 ruleset). Not in the SRD: names and mechanics as in the rules, with descriptions written for RealmForge in English and Italian.
///	</summary>
public static class WildMagic2014Seeder
{
	public static readonly Guid SubclassId = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "subclass", "wild-magic");

	public static Subclass Build()
	{
		return new Subclass
		{
			Id = SubclassId,
			CharacterClassId = Sorcerer2014Seeder.ClassId,
			Ruleset = RulesetVersion.Dnd5e_2014,
			IsOfficialSRD = true,
			Source = ContentSource.RealmForge,
			CasterProgression = CasterProgression.None,
			SpellcastingAbility = null,
			Translations = new List<SubclassTranslation>
			{
				new SubclassTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "subclass", "wild-magic", "en"), Language = LanguageCode.En, Name = "Wild Magic", Description = "Your power springs from the raw chaos beneath the order of creation. Perhaps you were exposed to unshaped magic through a planar rift, touched by a fey creature or marked by a fiend, or perhaps something inexplicable simply happened at your birth. Whatever the cause, that magic churns inside you and is always looking for a way out." },
				new SubclassTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "subclass", "wild-magic", "it"), Language = LanguageCode.It, Name = "Magia Selvaggia", Description = "Il potere dello stregone nasce dal caos primordiale che si cela sotto l'ordine del creato. Forse è stato esposto a una magia informe attraverso uno squarcio planare, toccato da una creatura fatata o marchiato da un immondo, oppure alla sua nascita è accaduto semplicemente qualcosa di inspiegabile. Qualunque sia la causa, quella magia ribolle dentro di lui e cerca sempre una via d'uscita." }
			},
			Features = new List<ClassFeature>
			{
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "wild-magic/wild-magic-surge"),
					Ruleset = RulesetVersion.Dnd5e_2014,
					Level = 1,
					SortOrder = 0,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "wild-magic/wild-magic-surge", "en"), Language = LanguageCode.En, Name = "Wild Magic Surge", Description = "From the moment you choose this origin at 1st level, your spells can unleash bursts of uncontrolled magic. Once per turn, right after you cast a sorcerer spell of 1st level or higher, the DM can ask you to roll a d20. On a 1, roll on the Wild Magic Surge table to create a random effect. If that effect is a spell, it is too wild to be affected by your Metamagic, and it lasts its full duration without needing concentration.\n\n**Wild Magic Surge**\n\n| d100 | Effect |\n|---|---|\n| 01–02 | For the next minute, roll on this table at the start of each of your turns, ignoring this result on later rolls. |\n| 03–04 | For the next minute, you can see invisible creatures you have line of sight to. |\n| 05–06 | A small clockwork construct controlled by the DM appears in an unoccupied space within 5 feet of you and vanishes after 1 minute. |\n| 07–08 | You cast *fireball* as a 3rd-level spell centered on yourself. |\n| 09–10 | You cast *magic missile* as a 5th-level spell. |\n| 11–12 | Roll a d10: your height changes by 1 inch × the result, shrinking on an odd roll and growing on an even one. |\n| 13–14 | You cast *confusion* centered on yourself. |\n| 15–16 | For the next minute, you regain 5 hit points at the start of each of your turns. |\n| 17–18 | A long beard of feathers sprouts from your chin and stays until you sneeze, when it bursts away harmlessly. |\n| 19–20 | You cast *grease* centered on yourself. |\n| 21–22 | Within the next minute, creatures have disadvantage on saving throws against the next spell you cast that calls for one. |\n| 23–24 | Your skin turns a bright shade of blue until a *remove curse* spell ends the effect. |\n| 25–26 | A third eye opens on your forehead for the next minute, giving you advantage on Wisdom (Perception) checks that rely on sight. |\n| 27–28 | For the next minute, every spell you cast with a casting time of 1 action has a casting time of 1 bonus action instead. |\n| 29–30 | You teleport up to 60 feet to an unoccupied space you can see. |\n| 31–32 | You are sent to the Astral Plane until the end of your next turn, then return to the space you left or the nearest unoccupied one. |\n| 33–34 | The next damaging spell you cast within the next minute deals maximum damage. |\n| 35–36 | Roll a d10: you grow younger (to a minimum of 1 year) by that many years on an odd roll, or older on an even one. |\n| 37–38 | 1d6 small, timid floating creatures controlled by the DM appear in unoccupied spaces within 60 feet of you; they are frightened of you and vanish after 1 minute. |\n| 39–40 | You regain 2d10 hit points. |\n| 41–42 | You become a potted plant until the start of your next turn: you are incapacitated and vulnerable to all damage, and if you drop to 0 hit points the pot shatters and you return to your normal form. |\n| 43–44 | For the next minute, you can teleport up to 20 feet as a bonus action on each of your turns. |\n| 45–46 | You cast *levitate* on yourself. |\n| 47–48 | A unicorn controlled by the DM appears in a space within 5 feet of you and vanishes after 1 minute. |\n| 49–50 | For the next minute you can't speak; whenever you try, pink bubbles drift out of your mouth. |\n| 51–52 | For the next minute, a spectral shield hovers beside you, granting +2 AC and immunity to *magic missile*. |\n| 53–54 | For the next 5d6 days, you can't become drunk on alcohol. |\n| 55–56 | All your hair falls out and grows back within 24 hours. |\n| 57–58 | For the next minute, any flammable object you touch that isn't worn or carried by another creature catches fire. |\n| 59–60 | You regain your lowest-level expended spell slot. |\n| 61–62 | For the next minute, you can only speak by shouting. |\n| 63–64 | You cast *fog cloud* centered on yourself. |\n| 65–66 | Up to three creatures of your choice within 30 feet of you take 4d10 lightning damage. |\n| 67–68 | You are frightened of the nearest creature until the end of your next turn. |\n| 69–70 | Every creature within 30 feet of you becomes invisible for the next minute; the invisibility ends for a creature when it attacks or casts a spell. |\n| 71–72 | You gain resistance to all damage for the next minute. |\n| 73–74 | A random creature within 60 feet of you is poisoned for 1d4 hours. |\n| 75–76 | For the next minute, you shed bright light in a 30-foot radius, and any creature that ends its turn within 5 feet of you is blinded until the end of its next turn. |\n| 77–78 | You cast *polymorph* on yourself; if you fail the saving throw, you become a sheep for the spell's duration. |\n| 79–80 | For the next minute, illusory butterflies and flower petals drift in the air within 10 feet of you. |\n| 81–82 | You can take one additional action immediately. |\n| 83–84 | Each creature within 30 feet of you takes 1d10 necrotic damage, and you regain hit points equal to the total necrotic damage dealt. |\n| 85–86 | You cast *mirror image*. |\n| 87–88 | You cast *fly* on a random creature within 60 feet of you. |\n| 89–90 | For the next minute, you are invisible and can't be heard; the effect ends if you attack or cast a spell. |\n| 91–92 | If you die within the next minute, you immediately come back to life as if by the *reincarnate* spell. |\n| 93–94 | Your size increases by one category for the next minute. |\n| 95–96 | You and every creature within 30 feet of you gain vulnerability to piercing damage for the next minute. |\n| 97–98 | For the next minute, faint ethereal music surrounds you. |\n| 99–00 | You regain all your expended sorcery points. |" },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "wild-magic/wild-magic-surge", "it"), Language = LanguageCode.It, Name = "Impulso di Magia Selvaggia", Description = "Dal momento in cui sceglie questa origine al 1° livello, gli incantesimi dello stregone possono scatenare scariche di magia incontrollata. Una volta per turno, subito dopo che lo stregone ha lanciato un incantesimo da stregone di 1° livello o superiore, il DM può chiedergli di tirare un d20. Con un 1, lo stregone tira sulla tabella degli Impulsi di Magia Selvaggia per generare un effetto casuale. Se quell'effetto è un incantesimo, è troppo selvaggio per essere influenzato dalla sua Metamagia e dura per tutta la sua durata senza bisogno di concentrazione.\n\n**Impulsi di Magia Selvaggia**\n\n| d100 | Effetto |\n|---|---|\n| 01–02 | Per il minuto successivo, lo stregone tira su questa tabella all'inizio di ogni suo turno, ignorando questo risultato nei tiri successivi. |\n| 03–04 | Per il minuto successivo, lo stregone vede le creature invisibili verso cui ha linea di vista. |\n| 05–06 | Un piccolo costrutto a orologeria controllato dal DM compare in uno spazio libero entro 1,5 metri dallo stregone e svanisce dopo 1 minuto. |\n| 07–08 | Lo stregone lancia *palla di fuoco* come incantesimo di 3° livello centrato su se stesso. |\n| 09–10 | Lo stregone lancia *dardo incantato* come incantesimo di 5° livello. |\n| 11–12 | Lo stregone tira un d10: la sua altezza cambia di 2,5 cm × il risultato, rimpicciolendo con un risultato dispari e crescendo con uno pari. |\n| 13–14 | Lo stregone lancia *confusione* centrato su se stesso. |\n| 15–16 | Per il minuto successivo, lo stregone recupera 5 punti ferita all'inizio di ogni suo turno. |\n| 17–18 | Sul mento dello stregone spunta una lunga barba di piume che rimane finché non starnutisce, quando si disperde senza fare danni. |\n| 19–20 | Lo stregone lancia *unto* centrato su se stesso. |\n| 21–22 | Nel minuto successivo, le creature subiscono svantaggio ai tiri salvezza contro il prossimo incantesimo dello stregone che ne richiede uno. |\n| 23–24 | La pelle dello stregone assume una vivace tonalità di blu finché un incantesimo *rimuovi maledizione* non pone fine all'effetto. |\n| 25–26 | Un terzo occhio si apre sulla fronte dello stregone per il minuto successivo, conferendogli vantaggio alle prove di Saggezza (Percezione) basate sulla vista. |\n| 27–28 | Per il minuto successivo, ogni incantesimo dello stregone con un tempo di lancio di 1 azione ha invece un tempo di lancio di 1 azione bonus. |\n| 29–30 | Lo stregone si teletrasporta fino a 18 metri in uno spazio libero che è in grado di vedere. |\n| 31–32 | Lo stregone viene spedito sul Piano Astrale fino alla fine del suo turno successivo, poi ritorna nello spazio che ha lasciato o in quello libero più vicino. |\n| 33–34 | Il prossimo incantesimo che infligge danni lanciato dallo stregone entro il minuto successivo infligge il massimo dei danni. |\n| 35–36 | Lo stregone tira un d10: ringiovanisce di quel numero di anni (fino a un minimo di 1 anno) con un risultato dispari, o invecchia con uno pari. |\n| 37–38 | 1d6 piccole creature fluttuanti e timorose controllate dal DM compaiono in spazi liberi entro 18 metri dallo stregone; sono spaventate da lui e svaniscono dopo 1 minuto. |\n| 39–40 | Lo stregone recupera 2d10 punti ferita. |\n| 41–42 | Lo stregone diventa una pianta in vaso fino all'inizio del suo turno successivo: è incapacitato e vulnerabile a tutti i danni, e se scende a 0 punti ferita il vaso va in frantumi e lo stregone torna alla sua forma normale. |\n| 43–44 | Per il minuto successivo, lo stregone può teletrasportarsi fino a 6 metri come azione bonus in ognuno dei suoi turni. |\n| 45–46 | Lo stregone lancia *levitazione* su se stesso. |\n| 47–48 | Un unicorno controllato dal DM compare in uno spazio entro 1,5 metri dallo stregone e svanisce dopo 1 minuto. |\n| 49–50 | Per il minuto successivo lo stregone non può parlare: ogni volta che ci prova, dalla sua bocca escono bolle rosa. |\n| 51–52 | Per il minuto successivo, uno scudo spettrale fluttua accanto allo stregone, conferendogli +2 alla CA e immunità a *dardo incantato*. |\n| 53–54 | Per i 5d6 giorni successivi, lo stregone non può ubriacarsi. |\n| 55–56 | Lo stregone perde tutti i capelli, che ricrescono entro 24 ore. |\n| 57–58 | Per il minuto successivo, qualsiasi oggetto infiammabile toccato dallo stregone che non sia indossato o trasportato da un'altra creatura prende fuoco. |\n| 59–60 | Lo stregone recupera lo slot incantesimo speso di livello più basso. |\n| 61–62 | Per il minuto successivo, lo stregone può parlare soltanto gridando. |\n| 63–64 | Lo stregone lancia *nube di nebbia* centrato su se stesso. |\n| 65–66 | Fino a tre creature a scelta dello stregone entro 9 metri da lui subiscono 4d10 danni da fulmine. |\n| 67–68 | Lo stregone è spaventato dalla creatura più vicina fino alla fine del suo turno successivo. |\n| 69–70 | Ogni creatura entro 9 metri dallo stregone diventa invisibile per il minuto successivo; l'invisibilità termina per una creatura quando attacca o lancia un incantesimo. |\n| 71–72 | Lo stregone ottiene resistenza a tutti i danni per il minuto successivo. |\n| 73–74 | Una creatura casuale entro 18 metri dallo stregone è avvelenata per 1d4 ore. |\n| 75–76 | Per il minuto successivo, lo stregone emette luce intensa in un raggio di 9 metri, e ogni creatura che termina il suo turno entro 1,5 metri da lui è accecata fino alla fine del suo turno successivo. |\n| 77–78 | Lo stregone lancia *metamorfosi* su se stesso; se fallisce il tiro salvezza, diventa una pecora per la durata dell'incantesimo. |\n| 79–80 | Per il minuto successivo, farfalle e petali illusori fluttuano nell'aria entro 3 metri dallo stregone. |\n| 81–82 | Lo stregone può effettuare immediatamente un'azione aggiuntiva. |\n| 83–84 | Ogni creatura entro 9 metri dallo stregone subisce 1d10 danni necrotici, e lo stregone recupera punti ferita pari al totale dei danni necrotici inflitti. |\n| 85–86 | Lo stregone lancia *immagine speculare*. |\n| 87–88 | Lo stregone lancia *volare* su una creatura casuale entro 18 metri da lui. |\n| 89–90 | Per il minuto successivo, lo stregone è invisibile e non può essere udito; l'effetto termina se attacca o lancia un incantesimo. |\n| 91–92 | Se lo stregone muore entro il minuto successivo, torna immediatamente in vita come per l'incantesimo *reincarnazione*. |\n| 93–94 | La taglia dello stregone aumenta di una categoria per il minuto successivo. |\n| 95–96 | Lo stregone e ogni creatura entro 9 metri da lui ottengono vulnerabilità ai danni perforanti per il minuto successivo. |\n| 97–98 | Per il minuto successivo, lo stregone è avvolto da una debole musica eterea. |\n| 99–00 | Lo stregone recupera tutti i punti stregoneria spesi. |" }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "wild-magic/tides-of-chaos"),
					Ruleset = RulesetVersion.Dnd5e_2014,
					Level = 1,
					SortOrder = 1,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "wild-magic/tides-of-chaos", "en"), Language = LanguageCode.En, Name = "Tides of Chaos", Description = "From 1st level, you can bend chance and chaos to gain advantage on one attack roll, ability check, or saving throw. Once you do, you can't use this feature again until you finish a long rest.\n\nBefore you regain it that way, the DM can have you roll on the Wild Magic Surge table right after you cast a sorcerer spell of 1st level or higher; you then regain the use of this feature." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "wild-magic/tides-of-chaos", "it"), Language = LanguageCode.It, Name = "Onde di Caos", Description = "Dal 1° livello lo stregone può piegare il caso e il caos per ottenere vantaggio a un tiro per colpire, una prova di caratteristica o un tiro salvezza. Una volta fatto, non può usare di nuovo questo privilegio finché non completa un riposo lungo.\n\nPrima che lo recuperi in questo modo, il DM può chiedergli di tirare sulla tabella degli Impulsi di Magia Selvaggia subito dopo che ha lanciato un incantesimo da stregone di 1° livello o superiore; in tal caso lo stregone recupera l'uso di questo privilegio." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "wild-magic/bend-luck"),
					Ruleset = RulesetVersion.Dnd5e_2014,
					Level = 6,
					SortOrder = 2,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "wild-magic/bend-luck", "en"), Language = LanguageCode.En, Name = "Bend Luck", Description = "From 6th level, your wild magic can twist fate. When a creature you can see makes an attack roll, ability check, or saving throw, you can use your reaction and spend 2 sorcery points to roll 1d4 and apply the result as a bonus or penalty (your choice) to its roll. You do so after the creature rolls but before any of the roll's effects occur." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "wild-magic/bend-luck", "it"), Language = LanguageCode.It, Name = "Piegare la Fortuna", Description = "Dal 6° livello la magia selvaggia dello stregone può distorcere il fato. Quando una creatura che lo stregone è in grado di vedere effettua un tiro per colpire, una prova di caratteristica o un tiro salvezza, lo stregone può usare la sua reazione e spendere 2 punti stregoneria per tirare 1d4 e applicarne il risultato come bonus o penalità (a sua scelta) al tiro della creatura. Lo fa dopo che la creatura ha tirato, ma prima che si verifichi qualsiasi effetto del tiro." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "wild-magic/controlled-chaos"),
					Ruleset = RulesetVersion.Dnd5e_2014,
					Level = 14,
					SortOrder = 3,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "wild-magic/controlled-chaos", "en"), Language = LanguageCode.En, Name = "Controlled Chaos", Description = "At 14th level, you gain some measure of control over your surges: whenever you roll on the Wild Magic Surge table, you can roll twice and use either number." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "wild-magic/controlled-chaos", "it"), Language = LanguageCode.It, Name = "Caos Controllato", Description = "Al 14° livello lo stregone ottiene un certo controllo sui suoi impulsi: ogni volta che tira sulla tabella degli Impulsi di Magia Selvaggia, può tirare due volte e usare uno dei due risultati." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "wild-magic/spell-bombardment"),
					Ruleset = RulesetVersion.Dnd5e_2014,
					Level = 18,
					SortOrder = 4,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "wild-magic/spell-bombardment", "en"), Language = LanguageCode.En, Name = "Spell Bombardment", Description = "From 18th level, your damaging spells hit even harder. When you roll damage for a spell and roll the highest possible number on any of the dice, choose one of those dice, roll it again, and add the new roll to the damage. You can use this feature only once per turn." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2014, "class-feature", "wild-magic/spell-bombardment", "it"), Language = LanguageCode.It, Name = "Bombardamento Magico", Description = "Dal 18° livello gli incantesimi dannosi dello stregone colpiscono ancora più forte. Quando tira per i danni di un incantesimo e ottiene il risultato più alto possibile su uno qualsiasi dei dadi, sceglie uno di quei dadi, lo tira di nuovo e aggiunge il nuovo risultato ai danni. Può usare questo privilegio soltanto una volta per turno." }
					}
				}
			}
		};
	}
}
